// The whole alphabet for a pen: capitals, figures, punctuation, extra letters and every composed accented capital,
// with Display's inlines when asked. Lowercase sets the same capitals (the faces are unicase), mapped by the fonts.
import { CAPITALS, INLINES } from "./capitals"
import {
  anchor,
  BARS,
  COMPOSED,
  EXTRA_INLINES,
  EXTRA_LETTERS,
  MARKS,
} from "./extras"
import { FIGURE_INLINES, FIGURES } from "./figures"
import { frame, type Def, type Pen, type Skeleton } from "./skeleton"

export const DISPLAY_PEN: Pen = { h: 10.5, ext: 1 }

const DEFS: Record<string, Def> = { ...CAPITALS, ...FIGURES, ...EXTRA_LETTERS }
const INLINE = { ...INLINES, ...FIGURE_INLINES, ...EXTRA_INLINES }

export function alphabet(
  pen: Pen,
  { inline = false } = {},
): Record<string, Skeleton> {
  const out: Record<string, Skeleton> = {}
  const frames: Record<string, ReturnType<typeof frame>> = {}
  for (const [char, [span, draw]] of Object.entries(DEFS)) {
    const f = frame(span, pen)
    frames[char] = f
    const g = draw(f)
    out[char] = { w: f.w, ...g, inl: inline ? (INLINE[char]?.(f) ?? []) : [] }
  }
  for (const [char, [base, ...parts]] of Object.entries(COMPOSED)) {
    const b = out[base]
    const f = frames[base]
    if (!b || !f) throw new Error(`no base ${base} for ${char}`)
    let d = b.d
    let marks = b.marks ?? ""
    for (const part of parts) {
      if (typeof part === "string") {
        const bar = BARS[part]
        if (!bar) throw new Error(`no bar ${part}`)
        d += ` ${bar(f)}`
      } else {
        const mark = MARKS[part[0]]
        if (!mark) throw new Error(`no mark ${part[0]}`)
        marks += ` ${mark(anchor(f, part[1]))}`
      }
    }
    out[char] = { ...b, d, marks: marks.trim() || undefined }
  }
  return out
}

/** Every character the alphabet draws, in code-point order. */
export const CHARACTERS = Object.keys({
  ...DEFS,
  ...COMPOSED,
}).sort((a, b) => a.codePointAt(0)! - b.codePointAt(0)!)

// The letters the capitals lack, the accents (drawn with a lighter mark pen) and every accented capital a
// Latin-script European language needs, composed from a base letter and its marks.
import {
  ccw,
  cw,
  dot,
  rr,
  v,
  type Def,
  type Frame,
  type Inline,
} from "./skeleton"

// prettier-ignore
export const EXTRA_LETTERS: Record<string, Def> = {
  Æ: [77, ({ l, r, t, b }) => {
    const [k, m] = [20, l + 40]
    return { d: `M ${l} ${b} V ${t + k} ${cw(k)} ${l + k} ${t} H ${r} M ${m} ${t} V ${b} H ${r} M ${m} 52 H ${r - 6} M ${l} 63 H ${m}`, inl: [] }
  }],
  Ø: [63, ({ l, r, t, b, w }) => ({ d: `${rr(l, t, r, b, 28)} M ${w + 4} -10 L -4 110`, inl: [], clip: true })],
  Œ: [85, ({ l, r, t, b }) => {
    const m = l + 52
    return { d: `M ${m} ${t} H ${l + 26} ${ccw(26)} ${l} ${t + 26} V ${b - 26} ${ccw(26)} ${l + 26} ${b} H ${r} M ${m} ${t} V ${b} M ${m} ${t} H ${r} M ${m} 50 H ${r - 6}`, inl: [] }
  }],
  Þ: [55, ({ l, r, t, b }) => ({ d: `M ${l} ${t} V ${b} M ${l} 22 H ${r - 18} ${cw(18)} ${r} 40 V 52 ${cw(18)} ${r - 18} 70 H ${l}`, inl: [] })],
  Ŋ: [59, ({ l, r, t, b }) => ({
    d: `M ${l} ${b} V ${t + 26} ${cw(26)} ${l + 26} ${t} H ${r - 26} ${cw(26)} ${r} ${t + 26} V 104 ${cw(14)} ${r - 14} 118 H ${r - 26}`,
    inl: [],
  })],
}

export const EXTRA_INLINES: Record<string, (f: Frame) => Inline[]> = {
  Æ: (f) => [v(f, f.l, f.t + 20, 92)],
  Ø: (f) => [v(f, f.l, f.t + 28, f.b - 28)],
  Œ: (f) => [v(f, f.l, f.t + 26, f.b - 26)],
  Þ: (f) => [v(f, f.l, 8, 92)],
  Ŋ: (f) => [v(f, f.l, f.t + 26, 92)],
}

/** Accents, centred on x, above the cap line (y < 0) or below the baseline (y > 100). Drawn with the mark pen. */
// prettier-ignore
export const MARKS: Record<string, (x: number) => string> = {
  acute: (x) => `M ${x - 6} -12 L ${x + 8} -28`,
  grave: (x) => `M ${x - 8} -28 L ${x + 6} -12`,
  circumflex: (x) => `M ${x - 13} -12 L ${x} -27 L ${x + 13} -12`,
  caron: (x) => `M ${x - 13} -27 L ${x} -12 L ${x + 13} -27`,
  dieresis: (x) => `${dot(x - 12, -18)} ${dot(x + 12, -18)}`,
  dot: (x) => dot(x, -18),
  ring: (x) => `M ${x - 9} -21 A 9 9 0 1 1 ${x + 9} -21 A 9 9 0 1 1 ${x - 9} -21 Z`,
  tilde: (x) => `M ${x - 15} -14 L ${x - 7} -23 L ${x + 7} -14 L ${x + 15} -23`,
  macron: (x) => `M ${x - 13} -18 H ${x + 13}`,
  breve: (x) => `M ${x - 12} -29 V -22 ${ccw(7)} ${x - 5} -15 H ${x + 5} ${ccw(7)} ${x + 12} -22 V -29`,
  doubleacute: (x) => `M ${x - 13} -12 L ${x - 5} -28 M ${x + 3} -12 L ${x + 11} -28`,
  ogonek: (x) => `M ${x} 100 V 110 ${ccw(6)} ${x + 6} 116 H ${x + 10}`,
  cedilla: (x) => `M ${x} 100 V 109 H ${x + 7} V 118 H ${x - 6}`,
  commabelow: (x) => `M ${x + 3} 106 V 110 L ${x - 2} 121`,
  apostrophe: (x) => `M ${x + 4} 0 V 8 L ${x} 20`,
}

/** Bars and strokes added to a base letter with the main pen. */
// prettier-ignore
export const BARS: Record<string, (f: Frame) => string> = {
  dbar: (f) => `M ${f.l - f.h * 0.4} 52 H ${f.l + 22}`,
  hbar: (f) => `M ${f.l} 26 H ${f.r}`,
  tbar: (f) => `M ${f.c - 16} 54 H ${f.c + 16}`,
  slash: (f) => `M ${f.l - 8} 64 L ${f.l + 16} 42`,
  middot: (f) => dot(f.l + 22, 54),
}

/** Where a mark sits: the centre, a stem, or an offset from the left stem. */
export type Anchor = "c" | "l" | "r" | number
export const anchor = (f: Frame, a: Anchor) =>
  a === "c" ? f.c : a === "l" ? f.l : a === "r" ? f.r : f.l + a

/** Every accented capital: base letter, then marks as [name, anchor] or bars by name. */
// prettier-ignore
export const COMPOSED: Record<string, [string, ...(string | [string, Anchor])[]]> = {
  À: ["A", ["grave", "c"]], Á: ["A", ["acute", "c"]], Â: ["A", ["circumflex", "c"]], Ã: ["A", ["tilde", "c"]],
  Ä: ["A", ["dieresis", "c"]], Å: ["A", ["ring", "c"]], Ā: ["A", ["macron", "c"]], Ă: ["A", ["breve", "c"]], Ą: ["A", ["ogonek", "r"]],
  Ç: ["C", ["cedilla", "c"]], Ć: ["C", ["acute", "c"]], Ĉ: ["C", ["circumflex", "c"]], Ċ: ["C", ["dot", "c"]], Č: ["C", ["caron", "c"]],
  Ď: ["D", ["caron", "c"]], Đ: ["D", "dbar"],
  È: ["E", ["grave", "c"]], É: ["E", ["acute", "c"]], Ê: ["E", ["circumflex", "c"]], Ë: ["E", ["dieresis", "c"]],
  Ē: ["E", ["macron", "c"]], Ĕ: ["E", ["breve", "c"]], Ė: ["E", ["dot", "c"]], Ę: ["E", ["ogonek", "r"]], Ě: ["E", ["caron", "c"]],
  Ĝ: ["G", ["circumflex", "c"]], Ğ: ["G", ["breve", "c"]], Ġ: ["G", ["dot", "c"]], Ģ: ["G", ["commabelow", "c"]],
  Ĥ: ["H", ["circumflex", "c"]], Ħ: ["H", "hbar"],
  Ì: ["I", ["grave", "c"]], Í: ["I", ["acute", "c"]], Î: ["I", ["circumflex", "c"]], Ï: ["I", ["dieresis", "c"]],
  Ĩ: ["I", ["tilde", "c"]], Ī: ["I", ["macron", "c"]], Ĭ: ["I", ["breve", "c"]], Į: ["I", ["ogonek", "l"]], İ: ["I", ["dot", "c"]],
  Ĵ: ["J", ["circumflex", "r"]], Ķ: ["K", ["commabelow", 14]],
  Ĺ: ["L", ["acute", "l"]], Ļ: ["L", ["commabelow", 14]], Ľ: ["L", ["apostrophe", 16]], Ŀ: ["L", "middot"], Ł: ["L", "slash"],
  Ñ: ["N", ["tilde", "c"]], Ń: ["N", ["acute", "c"]], Ņ: ["N", ["commabelow", "c"]], Ň: ["N", ["caron", "c"]],
  Ò: ["O", ["grave", "c"]], Ó: ["O", ["acute", "c"]], Ô: ["O", ["circumflex", "c"]], Õ: ["O", ["tilde", "c"]],
  Ö: ["O", ["dieresis", "c"]], Ō: ["O", ["macron", "c"]], Ŏ: ["O", ["breve", "c"]], Ő: ["O", ["doubleacute", "c"]],
  Ŕ: ["R", ["acute", "c"]], Ŗ: ["R", ["commabelow", 14]], Ř: ["R", ["caron", "c"]],
  Ś: ["S", ["acute", "c"]], Ŝ: ["S", ["circumflex", "c"]], Ş: ["S", ["cedilla", "c"]], Š: ["S", ["caron", "c"]], Ș: ["S", ["commabelow", "c"]],
  Ţ: ["T", ["cedilla", "c"]], Ť: ["T", ["caron", "c"]], Ŧ: ["T", "tbar"], Ț: ["T", ["commabelow", "c"]],
  Ù: ["U", ["grave", "c"]], Ú: ["U", ["acute", "c"]], Û: ["U", ["circumflex", "c"]], Ü: ["U", ["dieresis", "c"]],
  Ũ: ["U", ["tilde", "c"]], Ū: ["U", ["macron", "c"]], Ŭ: ["U", ["breve", "c"]], Ů: ["U", ["ring", "c"]], Ű: ["U", ["doubleacute", "c"]], Ų: ["U", ["ogonek", "c"]],
  Ŵ: ["W", ["circumflex", "c"]], Ẁ: ["W", ["grave", "c"]], Ẃ: ["W", ["acute", "c"]], Ẅ: ["W", ["dieresis", "c"]],
  Ý: ["Y", ["acute", "c"]], Ŷ: ["Y", ["circumflex", "c"]], Ÿ: ["Y", ["dieresis", "c"]], Ỳ: ["Y", ["grave", "c"]],
  Ź: ["Z", ["acute", "c"]], Ż: ["Z", ["dot", "c"]], Ž: ["Z", ["caron", "c"]],
}

/** Characters set with another glyph: look-alikes and the eth. */
export const SAME: [string, string][] = [
  ["Ð", "Đ"],
  ["‐", "-"],
  ["‑", "-"],
  ["′", "'"],
  ["″", '"'],
]

// Serigraph Mono: every glyph in one cell. Capitals and figures are the skeleton fitted to the cell; the lowercase is
// its own, on rounded-square bowls with flat-bottomed domes; the zero has two louver slots; ss01 steps the diagonals
// of 2, 7, Z and the slashes; four ornaments sit in the Private Use Area. Cap height 100, x-height 71.4% of it.
import { CHARACTERS } from "./alphabet"
import { CAPITALS } from "./capitals"
import { COMPOSED, EXTRA_LETTERS } from "./extras"
import { FIGURES } from "./figures"
import {
  ccw,
  cw,
  dot,
  frame,
  rr,
  type Def,
  type Frame,
  type Pen,
  type Skeleton,
} from "./skeleton"

/** The cell: 600 units at a cap height of 700, so 85.7 skeleton units; glyphs sit in a box inset by SB. */
export const MONO_CELL = 600 / 7
const SB = 9
const BOX = MONO_CELL - 2 * SB
export const MONO_PEN: Pen = { h: 5.4, ext: 1 }

// Lines for the lowercase: x-height, ascender and descender, as skeleton lines for the pen.
const X = 28.6
const ASC = -8.6
const DESC = 128.6

type Mono = (f: Frame & { x: number; a: number; d: number }) => string

// prettier-ignore
const LOWER: Record<string, Mono> = {
  a: ({ l, r, b, x }) => `${rr(l, x, r, b, 18)} M ${r} ${x} V ${b}`,
  b: ({ l, r, b, x, a }) => `${rr(l, x, r, b, 18)} M ${l} ${a} V ${b}`,
  c: ({ l, r, b, x }) => `M ${r} ${x} H ${l + 18} ${ccw(18)} ${l} ${x + 18} V ${b - 18} ${ccw(18)} ${l + 18} ${b} H ${r}`,
  d: ({ l, r, b, x, a }) => `${rr(l, x, r, b, 18)} M ${r} ${a} V ${b}`,
  e: ({ l, r, b, x }) => `M ${l} 64 H ${r} V ${x + 18} ${ccw(18)} ${r - 18} ${x} H ${l + 18} ${ccw(18)} ${l} ${x + 18} V ${b - 18} ${ccw(18)} ${l + 18} ${b} H ${r}`,
  f: ({ l, r, b, x, a, c }) => `M ${c - 6} ${b} V ${a + 18} ${cw(18)} ${c + 12} ${a} H ${r} M ${l} ${x} H ${r - 8}`,
  g: ({ l, r, b, x, d }) => `${rr(l, x, r, b - 6, 18)} M ${r} ${x} V ${d - 16} ${cw(16)} ${r - 16} ${d} H ${l}`,
  h: ({ l, r, b, x, a }) => { const k = (r - l) / 2; return `M ${l} ${a} V ${b} M ${l} ${b} V ${x + k} ${cw(k)} ${l + k} ${x} ${cw(k)} ${r} ${x + k} V ${b}` },
  i: ({ b, x, c }) => `M ${c - 16} ${x} H ${c} V ${b} M ${c - 18} ${b} H ${c + 18} ${dot(c, x - 18)}`,
  j: ({ l, x, c, d }) => `M ${c - 12} ${x} H ${c + 8} V ${d - 16} ${cw(16)} ${c - 8} ${d} H ${l} ${dot(c + 8, x - 18)}`,
  k: ({ l, r, b, x, a }) => `M ${l} ${a} V ${b} M ${r} ${x} L ${l + 2} 72 M ${l + 18} 62 L ${r} ${b}`,
  l: ({ b, a, c }) => `M ${c - 16} ${a} H ${c} V ${b} M ${c - 18} ${b} H ${c + 18}`,
  m: ({ l, r, b, x, c }) => {
    const k = (c - l) / 2
    return `M ${l} ${x} V ${b} M ${l} ${b} V ${x + k} ${cw(k)} ${l + k} ${x} ${cw(k)} ${c} ${x + k} V ${b} M ${c} ${x + k} ${cw(k)} ${c + k} ${x} ${cw(k)} ${r} ${x + k} V ${b}`
  },
  n: ({ l, r, b, x }) => { const k = (r - l) / 2; return `M ${l} ${x} V ${b} M ${l} ${b} V ${x + k} ${cw(k)} ${l + k} ${x} ${cw(k)} ${r} ${x + k} V ${b}` },
  o: ({ l, r, b, x }) => rr(l, x, r, b, 20),
  p: ({ l, r, b, x, d }) => `${rr(l, x, r, b, 18)} M ${l} ${x} V ${d}`,
  q: ({ l, r, b, x, d }) => `${rr(l, x, r, b, 18)} M ${r} ${x} V ${d}`,
  r: ({ l, r, b, x }) => `M ${l} ${x} V ${b} M ${l} ${b} V ${x + 20} ${cw(20)} ${l + 20} ${x} H ${r - 4}`,
  s: ({ l, r, b, x }) => {
    const m = (x + b) / 2
    const [k1, k2] = [(m - x) / 2, (b - m) / 2]
    return `M ${r} ${x} H ${l + k1} ${ccw(k1)} ${l} ${x + k1} ${ccw(k1)} ${l + k1} ${m} H ${r - k2} ${cw(k2)} ${r} ${m + k2} ${cw(k2)} ${r - k2} ${b} H ${l}`
  },
  t: ({ r, b, x, c, l }) => `M ${c - 8} ${x - 24} V ${b - 16} ${ccw(16)} ${c + 8} ${b} H ${r} M ${l} ${x} H ${r - 8}`,
  u: ({ l, r, b, x }) => { const k = (r - l) / 2; return `M ${l} ${x} V ${b - k} ${ccw(k)} ${l + k} ${b} ${ccw(k)} ${r} ${b - k} V ${x} M ${r} ${x} V ${b}` },
  v: ({ l, r, b, x, c }) => `M ${l} ${x} L ${c - 5} ${b} H ${c + 5} L ${r} ${x}`,
  w: ({ l, r, b, x, c }) => `M ${l} ${x} V ${b - 16} ${ccw(16)} ${l + 16} ${b} H ${r - 16} ${ccw(16)} ${r} ${b - 16} V ${x} M ${c} ${x + 12} V ${b}`,
  x: ({ l, r, b, x }) => `M ${l} ${x} L ${r} ${b} M ${r} ${x} L ${l} ${b}`,
  y: ({ l, r, b, x, d }) => `M ${l} ${x} V ${b - 16} ${ccw(16)} ${l + 16} ${b} H ${r} M ${r} ${x} V ${d - 16} ${cw(16)} ${r - 16} ${d} H ${l}`,
  z: ({ l, r, b, x }) => `M ${l} ${x} H ${r} L ${l} ${b} H ${r}`,
}

// prettier-ignore
const CODE: Record<string, Mono> = {
  I: ({ l, r, t, b, c }) => `M ${l + 8} ${t} H ${r - 8} M ${c} ${t} V ${b} M ${l + 8} ${b} H ${r - 8}`,
  1: ({ t, b, c }) => `M ${c - 18} 24 L ${c} ${t} V ${b} M ${c - 20} ${b} H ${c + 20}`,
  0: ({ l, r, t, b }) => `${rr(l, t, r, b, 22)} M ${l} 50 H ${l + 14} M ${r} 50 H ${r - 14}`,
  "<": ({ l, r }) => `M ${r} 42 L ${l} 64 L ${r} 86`,
  ">": ({ l, r }) => `M ${l} 42 L ${r} 64 L ${l} 86`,
  "[": ({ c }) => `M ${c + 14} -4 H ${c - 10} V 108 H ${c + 14}`,
  "]": ({ c }) => `M ${c - 14} -4 H ${c + 10} V 108 H ${c - 14}`,
  "{": ({ c }) => `M ${c + 14} -4 H ${c} V 44 L ${c - 14} 52 L ${c} 60 V 108 H ${c + 14}`,
  "}": ({ c }) => `M ${c - 14} -4 H ${c} V 44 L ${c + 14} 52 L ${c} 60 V 108 H ${c - 14}`,
  "\\": ({ l, r }) => `M ${l} -6 L ${r} 106`,
  "/": ({ l, r }) => `M ${r} -6 L ${l} 106`,
  "^": ({ l, r, c }) => `M ${l + 6} 40 L ${c} 12 L ${r - 6} 40`,
  _: ({ l, r }) => `M ${l} 112 H ${r}`,
  "`": ({ c }) => `M ${c - 7} 2 L ${c + 6} 18`,
  "|": ({ c }) => `M ${c} -10 V 112`,
  "~": ({ l, r }) => `M ${l} 62 L ${l + 16} 50 L ${r - 16} 70 L ${r} 58`,
}

/** ss01: the diagonals of 2, 7, Z and the slashes as three-step staircases. */
// prettier-ignore
export const STEPPED: Record<string, Mono> = {
  "2": ({ l, r, t, b }) => `M ${l} ${t} H ${r} V 36 H ${(l + r) / 2} V 66 H ${l} V ${b} H ${r}`,
  "7": ({ l, r, t, b }) => { const s = (r - l) / 3; return `M ${l} ${t} H ${r} V 36 H ${r - s} V 66 H ${r - 2 * s} V ${b}` },
  Z: ({ l, r, t, b }) => `M ${l} ${t} H ${r} V 36 H ${(l + r) / 2} V 66 H ${l} V ${b} H ${r}`,
  "/": ({ l, r, t, b }) => { const s = (r - l) / 3; return `M ${l} ${b} V 66 H ${l + s} V 36 H ${l + 2 * s} V ${t} H ${r}` },
  "\\": ({ l, r, t, b }) => { const s = (r - l) / 3; return `M ${l} ${t} H ${l + s} V 36 H ${l + 2 * s} V 66 H ${r} V ${b}` },
}

/** The four ornaments, in the Private Use Area: sparkle, double ring, louvers and a cloud tile. */
export const ORNAMENTS: Record<string, string> = {
  "": "sparkle",
  "": "rings",
  "": "louvers",
  "": "cloud",
}
// prettier-ignore
const ORNAMENT: Record<string, Mono> = {
  sparkle: ({ c }) => `M ${c} 6 A 40 40 0 0 0 ${c + 34} 46 A 40 40 0 0 0 ${c} 86 A 40 40 0 0 0 ${c - 34} 46 A 40 40 0 0 0 ${c} 6 Z`,
  rings: ({ c }) => `M ${c - 30} 50 A 30 30 0 1 1 ${c + 30} 50 A 30 30 0 1 1 ${c - 30} 50 Z M ${c - 14} 50 A 14 14 0 1 1 ${c + 14} 50 A 14 14 0 1 1 ${c - 14} 50 Z`,
  louvers: ({ l, r }) => `M ${l} 36 H ${r} M ${l} 60 H ${r} M ${l} 84 H ${r}`,
  cloud: () => {
    // Open at both cell edges, so a run of tiles makes one bank: three puffs over a flat baseline.
    const [w, k] = [MONO_CELL, MONO_CELL / 6]
    return `M ${-SB} 96 H ${w - SB} M ${-SB} 60 A ${k} ${k} 0 0 1 ${-SB + 2 * k} 60 A ${k * 1.3} ${k * 1.3} 0 0 1 ${-SB + 4 * k} 60 A ${k} ${k} 0 0 1 ${w - SB} 60`
  },
}

const cellFrame = (p: Pen) => {
  const f = frame(BOX - 2 * p.h, p)
  return { ...f, x: X + p.h, a: ASC + p.h, d: DESC - p.h }
}
/** A skeleton definition fitted to the cell: its span stretched or squeezed, centred when it is narrow. */
function fit([span, draw]: Def, p: Pen): Skeleton {
  const inner = BOX - 2 * p.h
  if (span >= 30) {
    const f = frame(span, { ...p, ext: inner / span })
    return { ...draw(f), w: BOX, inl: [] }
  }
  const f = frame(span, p)
  const g = draw(f)
  const dx = (BOX - f.w) / 2
  const shift = (d?: string) => d && shiftX(d, dx)
  return { ...g, d: shiftX(g.d, dx), marks: shift(g.marks), w: BOX, inl: [] }
}
/** Move every x in M, L, H and A commands of a path by dx. */
function shiftX(d: string, dx: number) {
  return d.replace(/([MLHA])([^MLHVAZ]*)/g, (_, cmd: string, args: string) => {
    const n = args
      .trim()
      .split(/[\s,]+/)
      .filter(Boolean)
      .map(Number)
    if (cmd === "H") return `H ${n[0]! + dx} `
    if (cmd === "A")
      return `A ${n.slice(0, 5).join(" ")} ${n[5]! + dx} ${n[6]} `
    const out: number[] = []
    for (let i = 0; i < n.length; i += 2) out.push(n[i]! + dx, n[i + 1]!)
    return `${cmd} ${out.join(" ")} `
  })
}

/** Every mono glyph: [char, skeleton, ink right to the cell's edges]. */
export function monoAlphabet(p: Pen = MONO_PEN) {
  const f = cellFrame(p)
  const out: Record<string, Skeleton & { bleed?: boolean }> = {}
  const own = (fn: Mono): Skeleton => ({ w: BOX, d: fn(f), inl: [] })
  const defs: Record<string, Def> = {
    ...CAPITALS,
    ...FIGURES,
    ...EXTRA_LETTERS,
  }
  for (const c of CHARACTERS) {
    if (c in COMPOSED || c === " ") continue
    out[c] = CODE[c] ? own(CODE[c]) : fit(defs[c]!, p)
  }
  for (const [c, draw] of Object.entries(LOWER)) out[c] = own(draw)
  for (const [c, draw] of Object.entries(CODE)) out[c] = own(draw)
  for (const [c, name] of Object.entries(ORNAMENTS))
    out[c] = { ...own(ORNAMENT[name]!), bleed: name === "cloud" }
  const stepped = Object.fromEntries(
    Object.entries(STEPPED).map(([c, draw]) => [c, own(draw)]),
  )
  return { glyphs: out, stepped, box: BOX, sb: SB, x: X }
}

// Serigraph's skeleton alphabet: every capital and figure as centre lines at cap height 100 (y down from the cap line,
// a glyph from x = 0 to its width), swept by a square pen. Serigraph Display sweeps it with a heavy pen and draws an
// inline beside each left stem; Serigraph Sans sweeps it with a light pen and a wider span. tools/fonts builds the
// fonts from it; the static specimen's lettering.js is its prototype. Framework-free: no React, no DOM.

/** A pen: half its width (h) and how much wider than Display's the letters are set (ext, 1 for Display). */
export interface Pen {
  h: number
  ext: number
}

/** One inline: a straight line [x1, y1, x2, y2] beside a stem. */
export type Inline = [number, number, number, number]

export interface Skeleton {
  /** The glyph's width; the pen's ink stays inside 0..w (diagonals are cut by the box when clip is set). */
  w: number
  /** Centre lines as SVG path data: M, L, H, V, A and Z. */
  d: string
  /** Strokes drawn with the lighter mark pen (accents, bars). */
  marks?: string
  /** Inlines beside the left stems (Display only). */
  inl: Inline[]
  /** Diagonals run past the box and are cut flat by it. */
  clip?: boolean
}

/** Geometry a glyph is drawn in: left and right skeleton lines, width, top and bottom lines, centre, half-pen. */
export interface Frame {
  l: number
  r: number
  w: number
  t: number
  b: number
  c: number
  h: number
}

type Draw = (f: Frame) => Omit<Skeleton, "w">
/** [inner span between the skeleton lines at ext 1, drawing]. */
export type Def = [number, Draw]

export const cw = (k: number) => `A ${k} ${k} 0 0 1`
export const ccw = (k: number) => `A ${k} ${k} 0 0 0`
/** An inline beside a vertical stem at x, from y1 to y2, a little toward the outer edge. */
export const v = (f: Frame, x: number, y1: number, y2: number): Inline => [
  x - f.h * 0.38,
  y1,
  x - f.h * 0.38,
  y2,
]
/** An inline beside a diagonal from (x1, y1) to (x2, y2), over fractions f0..f1 of it, on its outer (left) side. */
export function diag(
  f: Frame,
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  f0: number,
  f1: number,
): Inline {
  const [dx, dy] = [x2 - x1, y2 - y1]
  const len = Math.hypot(dx, dy)
  const [ox, oy] = [(-dy / len) * f.h * 0.38, (dx / len) * f.h * 0.38]
  return [
    x1 + dx * f0 + ox,
    y1 + dy * f0 + oy,
    x1 + dx * f1 + ox,
    y1 + dy * f1 + oy,
  ]
}
/** A closed rounded rectangle. */
export const rr = (x0: number, y0: number, x1: number, y1: number, k: number) =>
  `M ${x0 + k} ${y0} H ${x1 - k} ${cw(k)} ${x1} ${y0 + k} V ${y1 - k} ${cw(k)} ${x1 - k} ${y1} ` +
  `H ${x0 + k} ${cw(k)} ${x0} ${y1 - k} V ${y0 + k} ${cw(k)} ${x0 + k} ${y0} Z`
/** A dot at (x, y): a zero-length stroke the square pen turns into a square. */
export const dot = (x: number, y: number) => `M ${x} ${y - 0.01} V ${y}`
/** A round dot: a tight ring the pen fills. */
export const disc = (x: number, y: number, k = 4) =>
  `M ${x - k} ${y} A ${k} ${k} 0 1 1 ${x + k} ${y} A ${k} ${k} 0 1 1 ${x - k} ${y} Z`

/** The frame for a glyph of inner span `span` drawn with pen p. */
export function frame(span: number, p: Pen): Frame {
  const w = span * p.ext + 2 * p.h
  return { l: p.h, r: w - p.h, w, t: p.h, b: 100 - p.h, c: w / 2, h: p.h }
}

/** Draw a definition with a pen. */
export function draw([span, fn]: Def, p: Pen): Skeleton {
  const f = frame(span, p)
  return { w: f.w, ...fn(f) }
}
